#!/usr/bin/env python3
"""Look up a verse in a dataset generated by import_web_archive.py."""
import argparse
import json
import re
import sys
from pathlib import Path

# Names are an explicit alias map, not a versification conversion.
NAMES = {
    'GEN': 'Genesis', 'EXO': 'Exodus', 'LEV': 'Leviticus', 'NUM': 'Numbers', 'DEU': 'Deuteronomy',
    'JOS': 'Joshua', 'JDG': 'Judges', 'RUT': 'Ruth', '1SA': '1 Samuel', '2SA': '2 Samuel',
    '1KI': '1 Kings', '2KI': '2 Kings', '1CH': '1 Chronicles', '2CH': '2 Chronicles',
    'EZR': 'Ezra', 'NEH': 'Nehemiah', 'EST': 'Esther', 'JOB': 'Job', 'PSA': 'Psalms',
    'PRO': 'Proverbs', 'ECC': 'Ecclesiastes', 'SNG': 'Song of Solomon', 'ISA': 'Isaiah',
    'JER': 'Jeremiah', 'LAM': 'Lamentations', 'EZK': 'Ezekiel', 'DAN': 'Daniel',
    'HOS': 'Hosea', 'JOL': 'Joel', 'AMO': 'Amos', 'OBA': 'Obadiah', 'JON': 'Jonah',
    'MIC': 'Micah', 'NAM': 'Nahum', 'HAB': 'Habakkuk', 'ZEP': 'Zephaniah', 'HAG': 'Haggai',
    'ZEC': 'Zechariah', 'MAL': 'Malachi', 'MAT': 'Matthew', 'MRK': 'Mark', 'LUK': 'Luke',
    'JHN': 'John', 'ACT': 'Acts', 'ROM': 'Romans', '1CO': '1 Corinthians', '2CO': '2 Corinthians',
    'GAL': 'Galatians', 'EPH': 'Ephesians', 'PHP': 'Philippians', 'COL': 'Colossians',
    '1TH': '1 Thessalonians', '2TH': '2 Thessalonians', '1TI': '1 Timothy', '2TI': '2 Timothy',
    'TIT': 'Titus', 'PHM': 'Philemon', 'HEB': 'Hebrews', 'JAS': 'James', '1PE': '1 Peter',
    '2PE': '2 Peter', '1JN': '1 John', '2JN': '2 John', '3JN': '3 John', 'JUD': 'Jude', 'REV': 'Revelation',
}


def normalize(value):
    return re.sub(r'[\s.]+', '', value.casefold())


ALIASES = {normalize(name): code for code, name in NAMES.items()}
ALIASES.update({normalize(code): code for code in NAMES})
ALIASES.update({'psalm': 'PSA', 'songofsongs': 'SNG', 'songofsolomon': 'SNG', 'revelations': 'REV'})

# Russian Synodal book names. 1–4 Царств correspond to USFM 1SA–2KI.
RUSSIAN_NAMES = {
    'GEN': 'Бытие', 'EXO': 'Исход', 'LEV': 'Левит', 'NUM': 'Числа', 'DEU': 'Второзаконие',
    'JOS': 'Иисус Навин', 'JDG': 'Судьи', 'RUT': 'Руфь', '1SA': '1 Царств', '2SA': '2 Царств',
    '1KI': '3 Царств', '2KI': '4 Царств', '1CH': '1 Паралипоменон', '2CH': '2 Паралипоменон',
    'EZR': 'Ездра', 'NEH': 'Неемия', 'EST': 'Есфирь', 'JOB': 'Иов', 'PSA': 'Псалтирь',
    'PRO': 'Притчи', 'ECC': 'Екклесиаст', 'SNG': 'Песнь Песней', 'ISA': 'Исаия', 'JER': 'Иеремия',
    'LAM': 'Плач Иеремии', 'EZK': 'Иезекииль', 'DAN': 'Даниил', 'HOS': 'Осия', 'JOL': 'Иоиль',
    'AMO': 'Амос', 'OBA': 'Авдий', 'JON': 'Иона', 'MIC': 'Михей', 'NAM': 'Наум', 'HAB': 'Аввакум',
    'ZEP': 'Софония', 'HAG': 'Аггей', 'ZEC': 'Захария', 'MAL': 'Малахия', 'MAT': 'Матфея',
    'MRK': 'Марка', 'LUK': 'Луки', 'JHN': 'Иоанна', 'ACT': 'Деяния', 'ROM': 'Римлянам',
    '1CO': '1 Коринфянам', '2CO': '2 Коринфянам', 'GAL': 'Галатам', 'EPH': 'Ефесянам',
    'PHP': 'Филиппийцам', 'COL': 'Колоссянам', '1TH': '1 Фессалоникийцам', '2TH': '2 Фессалоникийцам',
    '1TI': '1 Тимофею', '2TI': '2 Тимофею', 'TIT': 'Титу', 'PHM': 'Филимону', 'HEB': 'Евреям',
    'JAS': 'Иакова', '1PE': '1 Петра', '2PE': '2 Петра', '1JN': '1 Иоанна', '2JN': '2 Иоанна',
    '3JN': '3 Иоанна', 'JUD': 'Иуды', 'REV': 'Откровение',
}
ALIASES.update({normalize(name): code for code, name in RUSSIAN_NAMES.items()})
ALIASES.update({normalize(name): code for name, code in {
    'Псалом': 'PSA', 'Псалмы': 'PSA', 'Пс': 'PSA', 'Ин': 'JHN', 'От Иоанна': 'JHN',
    'Быт': 'GEN', 'Рим': 'ROM', 'Римлянам': 'ROM', 'Матфей': 'MAT',
    'Мф': 'MAT', 'Мк': 'MRK', 'Лк': 'LUK', 'Деян': 'ACT',
}.items()})



def parse_reference(reference):
    match = re.fullmatch(r'\s*(.+?)\s+(\d+):(\d+)\s*', reference)
    if not match:
        raise ValueError('Use a reference such as "John 3:16" or "1 John 4:8".')
    book = ALIASES.get(normalize(match.group(1)))
    if book is None:
        raise ValueError(f'Unknown book: {match.group(1)}. Use the full English name or USFM code.')
    chapter, verse = int(match.group(2)), int(match.group(3))
    if chapter < 1 or verse < 1:
        raise ValueError('Chapter and verse numbers must be positive.')
    return book, chapter, verse


def read_note(raw):
    # Render note text conservatively; retain the source reference separately.
    ref = re.search(r'\\(?:fr|xo)\s+(.*?)(?=\\(?:ft|xt)\b)', raw, re.DOTALL)
    content = re.search(r'\\(?:ft|xt)\s+(.*?)(?=\\(?:f|x)\*$)', raw, re.DOTALL)
    if not ref or not content:
        return None
    text = re.sub(r'\\\+?[a-zA-Z0-9]+\*', '', content.group(1))
    text = re.sub(r'\\\+?[a-zA-Z0-9]+ ?', '', text)
    return ' '.join(ref.group(1).split()), ' '.join(text.split())


def lookup(directory, reference):
    code, chapter, number = parse_reference(reference)
    manifest_file = directory / 'manifest.json'
    if not manifest_file.is_file():
        raise ValueError(f'No manifest.json found in {directory}. Generate the dataset first.')
    manifest = json.loads(manifest_file.read_text(encoding='utf-8'))
    book_file = directory / f'{code}.json'
    if not book_file.is_file():
        raise ValueError(f'Dataset is missing {code}.json. Regenerate the dataset.')
    book = json.loads(book_file.read_text(encoding='utf-8'))
    if book.get('book') != code:
        raise ValueError(f'{code}.json has an unexpected book identifier.')
    matches = [v for v in book['verses'] if v['chapter'] == chapter and v['verse'] == number]
    if len(matches) != 1:
        raise ValueError(f'{NAMES[code]} {chapter}:{number} was not found uniquely in this dataset.')
    return code, chapter, number, matches[0], book, manifest


def format_result(result):
    code, chapter, number, verse, book, manifest = result
    name = RUSSIAN_NAMES.get(code, NAMES[code]) if manifest.get('language') == 'ru' else NAMES[code]
    lines = [f'{name} {chapter}:{number}', verse['text'] or '[No verse text in this source.]']
    for item in verse.get('notes', []):
        title = 'Footnote' if item.get('type') == 'footnote' else 'Cross-reference'
        parsed = read_note(item['raw_usfm'])
        if parsed:
            ref, text = parsed
            lines.append(f'{title} ({ref}): {text}')
        else:
            lines.append(f"{title} (original USFM): {item['raw_usfm']}")
    lines += ['', f"Source: {manifest.get('edition', 'Unknown edition')}",
              f"Source file: {book.get('source_file', 'unknown')}",
              f"Archive SHA-256: {manifest.get('archive_sha256', 'unknown')}"]
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('reference', help='Quoted reference, e.g. "John 3:16"')
    parser.add_argument('--data', type=Path, default=Path('output/web'), help='Generated dataset directory (default: output/web)')
    args = parser.parse_args()
    try:
        print(format_result(lookup(args.data, args.reference)))
    except (ValueError, KeyError, OSError, json.JSONDecodeError) as exc:
        print(f'Error: {exc}', file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
